(function() {
  // Acordeón de categorías — una abierta a la vez
  document.querySelectorAll('.brilla-cat-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var target = document.getElementById(btn.getAttribute('data-target'));
      var isOpen = target.style.display === 'block';
      document.querySelectorAll('.brilla-cat-content').forEach(function(c) { c.style.display = 'none'; });
      document.querySelectorAll('.brilla-cat-icon').forEach(function(i) { i.textContent = '+'; });
      if (!isOpen) {
        target.style.display = 'block';
        btn.querySelector('.brilla-cat-icon').textContent = '\u2212';
      }
    });
  });

  // Acordeón de oportunidades — una abierta a la vez DENTRO de cada categoría
  document.querySelectorAll('.brilla-op-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var categoria = btn.closest('.brilla-cat-content');
      var target = document.getElementById(btn.getAttribute('data-target'));
      var isOpen = target.style.display === 'block';
      categoria.querySelectorAll('.brilla-op-content').forEach(function(c) { c.style.display = 'none'; });
      categoria.querySelectorAll('.brilla-op-icon').forEach(function(i) { i.textContent = '+'; });
      if (!isOpen) {
        target.style.display = 'block';
        btn.querySelector('.brilla-op-icon').textContent = '\u2212';
      }
    });
  });

  // Botones de copiar al portapapeles (Lo que puedes decir / TU Siguiente Paso)
  document.querySelectorAll('.brilla-btn-copiar').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      var texto = btn.getAttribute('data-texto');
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(texto).then(function() {
          var original = btn.textContent;
          btn.textContent = 'Copiado ✓';
          setTimeout(function() { btn.textContent = original; }, 1500);
        });
      }
    });
  });
})();
